function h({registerIndicator:f,sourceValues:m,nulls:y}){f({id:"oa-psl",name:"Psychological Line (PSL)",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:12,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"psl",type:"line",title:"PSL",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:50,title:"Midline",color:"#787b86",dashed:!0},{price:75,title:"Overbought",color:"#ff5252",dashed:!0},{price:25,title:"Oversold",color:"#4caf50",dashed:!0}],range:()=>({min:0,max:100}),calc(o,r){const c=Math.max(1,Math.floor(Number(r.period)||12)),i=m(o,r.source??"close"),l=o.length,a=new Array(l).fill(0),s=new Array(l).fill(NaN);let t=0,n=0;for(let e=0;e<l;e++){const u=e>=1?i[e-1]:NaN,p=i[e],d=Number.isFinite(u)&&Number.isFinite(p)&&p>u?1:0;e>=c?t-=a[e-c]:n+=1,t+=d,a[e]=d,s[e]=100*t/Math.max(1,n)}return{psl:y(s)}}})}export{h as default};
